                    rewards = otherSegmentData[i].keepRewards
                })
            end
            if otherSegmentData[i].downGrade ~= 0 then
                table.insert(items, {
                    isCurRankArea = isCurSegment and self:IsInArea(myRank, otherSegmentData[i].downGrade[1], otherSegmentData[i].downGrade[2]),
                    status = 3,
                    title = string.format("%s <size=24>th</size>~ %s <size=24>th</size>", otherSegmentData[i].downGrade[1], otherSegmentData[i].downGrade[2]),
                    desc = otherSegmentData[i].downGradeText,
                    --rewards = parse_rewards(otherSegmentData[i].downPrizeId, otherSegmentData[i].downPrizeNum)
                    rewards = otherSegmentData[i].downRewards
                })
            end
            table.insert(togglesData, {
                text = otherSegmentData[i].name,
                --lock = isCurSegment,
                func = function()
                    self:FreshUI({
                        name = otherSegmentData[i].name,
                        status = otherSegmentData[i].icon,
                        items = items,
                    })
                end
            })
        end
        --table.insert(togglesData, {
