function TrailStageParagraphReward:IsInArea(target, min, max)
    target = checkNumber(target)
    min = checkNumber(min)
    max = checkNumber(max)
    return target >= min and target <= max
end

function TrailStageParagraphReward:FreshUI(data)
    self.Text.text = data.name
    self.ImgLevel.Status = data.status
    if #self.itemGoList > #data.items then--复用时隐藏多出来的
        for i = #data.items + 1, #self.itemGoList do
            KTool.SetActive(self.itemGoList[i].gameObject, false)
        end
    end
    for i = 1, #data.items do
        local go
        go = self.itemGoList[i]
        if not go then
            go = CfUtils.InstantiateGo(self.Item, self.LayoutRight)
            go.name = "go"..i
            self.itemGoList[i] = go.gameObject
        end
        KTool.SetActive(go, true)
        local goEnv = CfUtils.GetLuaScr(go, "Game.UI.TrailStage.TrailStageParagraphRewardCell")
        goEnv:FreshBaseUI(data.items[i])
    end
end

function TrailStageParagraphReward:OnFinalize()
    local coWait = CoWait.Start():Coroutine(util.cs_generator(function()
        self.controller = nil --删除lua层引用到的c#对象 否则不会产生c# gc回收到对象
        self:Delete()
        self = nil --lua层的gc需要
    end))
    return coWait
end

return TrailStageParagraphReward